:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-button { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; padding: 11px 18px; border: 1px solid var(--accent, #1c756e); border-radius: var(--radius-control, 8px); background: var(--accent, #1c756e); color: white; font-weight: 650; font-size: 13px; line-height: 1.4; text-decoration: none; transition: background var(--duration-fast, 150ms), border-color var(--duration-fast, 150ms), color var(--duration-fast, 150ms), transform var(--duration-fast, 150ms); }
.ds-button:hover:not(:disabled) { background: var(--accent-hover, #155e58); border-color: var(--accent-hover, #155e58); }
.ds-button:active:not(:disabled) { transform: translateY(1px); }
.ds-button:disabled { opacity: .5; }
:focus-visible { outline: 3px solid #368f82; outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; } }

