:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-form label { display: grid; gap: 9px; color: var(--text, #17252b); font-size: 13px; font-weight: 650; }
.ds-form input, .ds-form textarea, .ds-form select { width: 100%; min-height: 46px; padding: 12px 14px; background: #fdfefb; color: var(--text, #17252b); border: 1px solid #c9d3c6; border-radius: var(--radius-control, 8px); font-weight: 450; font-size: 14px; line-height: 1.5; transition: background var(--duration-fast, 150ms), border-color var(--duration-fast, 150ms), box-shadow var(--duration-fast, 150ms); }
.ds-form input::placeholder, .ds-form textarea::placeholder { color: var(--muted, #61716e); opacity: 1; }
.ds-form input:hover, .ds-form textarea:hover, .ds-form select:hover { border-color: #819b85; }
.ds-form input:focus-visible, .ds-form textarea:focus-visible, .ds-form select:focus-visible { outline: 2px solid #3d8c73; outline-offset: 2px; border-color: var(--accent, #1c756e); background: white; }
.ds-form input:disabled, .ds-form textarea:disabled, .ds-form select:disabled { background: #eef1e9; opacity: .7; }
