:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-workspace-nav { display: grid; gap: 6px; }
.ds-workspace-nav a { display: flex; align-items: center; gap: 13px; min-height: 48px; padding: 12px; text-decoration: none; font-size: 14px; font-weight: 550; color: var(--sidebar-muted, #afbfbe); border: 1px solid transparent; border-radius: var(--radius-control, 8px); transition: background var(--duration-fast, 150ms), color var(--duration-fast, 150ms), border-color var(--duration-fast, 150ms); }
.ds-workspace-nav a span { flex: 1; }
.ds-workspace-nav a > svg:last-child { opacity: 0; transition: opacity var(--duration-fast, 150ms), transform var(--duration-fast, 150ms); transform: translateX(-3px); }
.ds-workspace-nav a:hover { color: #ffffff; background: #20353a; }
.ds-workspace-nav a.ds-active { color: #f4f8f0; background: #2a4544; border-color: #3b5751; font-weight: 650; }
.ds-workspace-nav a.ds-active > svg:last-child { opacity: .8; transform: none; }
:focus-visible { outline: 3px solid #368f82; outline-offset: 4px; }
