.ds-workspace-nav { background: var(--sidebar, #15242a); }

:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-badge { --status-color: #596968; --status-bg: #eff2ef; display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; color: var(--status-color, #a24e32); background: var(--status-bg, #fcefe6); border: 1px solid color-mix(in srgb, var(--status-color, #a24e32) 12%, transparent); border-radius: 6px; font-size: 12px; font-weight: 650; line-height: 1.35; white-space: nowrap; width: fit-content; }
.ds-badge.ds-status-new { --status-color: #596968; --status-bg: #eff2ef; }

:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-panel { border: 1px solid var(--line, #dfe4dc); border-radius: var(--radius, 12px); padding: 28px; background: white; min-width: 0; }
.ds-panel-heading { display: flex; align-items: center; gap: 10px; margin-bottom: 20px; }
.ds-panel-heading h2 { font-size: 17px; }

:host { font-family: 'Manrope Variable', 'Manrope', sans-serif; font-size: 15px; line-height: 1.55; color: var(--text, #17252b); }
.ds-object-row { display: flex; align-items: center; gap: 22px; padding: 27px 28px; border-bottom: 1px solid var(--line, #dfe4dc); color: var(--text, #17252b); text-decoration: none; transition: background var(--duration-normal, 200ms), transform var(--duration-fast, 150ms); }
.ds-object-row:hover { background: #f9fbf5; }
.ds-object-row:focus-visible { outline-offset: -4px; background: #f4f8ef; }
.ds-object-row:active { background: #eef4e9; }
.ds-object-text { flex: 1; min-width: 0; display: grid; gap: 8px; }
.ds-object-text strong { font-size: 17px; font-weight: 700; letter-spacing: -.02em; overflow-wrap: anywhere; }
.ds-object-text > span { color: var(--muted, #61716e); font-size: 13px; display: flex; align-items: flex-start; gap: 6px; overflow-wrap: anywhere; }
.ds-row-arrow { display: grid; place-items: center; width: 36px; height: 36px; margin-left: 8px; color: #73877a; transition: transform var(--duration-normal, 200ms) var(--ease-out, cubic-bezier(.22, 1, .36, 1)), color var(--duration-normal, 200ms); }
.ds-object-row:hover .ds-row-arrow { color: var(--accent, #1c756e); transform: translate(2px, -2px); }
